SELECT current_database() AS database_name,session_user::text AS login,current_user::text AS actor,(pg_control_system()).system_identifier::text AS system_identifier;
SELECT p.oid::regprocedure::text AS signature,encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex') AS definition_sha256,encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') AS body_sha256,pg_get_function_arguments(p.oid) AS arguments,pg_get_userbyid(p.proowner) AS owner,p.prosecdef,p.proisstrict,p.provolatile,p.proparallel,p.proconfig,p.proacl::text AS acl,
