FROM pg_proc p WHERE p.oid=ANY(ARRAY['rakeezx.apply_n58_empty_foundation(text,jsonb)','rakeezx.apply_reviewed_grade_import(text,text,jsonb)','rakeezx.apply_score_configuration_command(text,text,text,bigint,jsonb)','rakeezx.apply_score_distribution_copy_command(text,text,text,bigint,text,text,jsonb,text)','rakeezx.apply_score_distribution_plan(text,text,text,text,boolean)','rakeezx.apply_score_subitem_command(text,text,text,text,text,text,boolean,numeric)','rakeezx.apply_score_subitem_command_n94(text,text,text,text,text,text,text,numeric)','rakeezx.apply_student_lifecycle_command(text,text,text,jsonb,bigint)','rakeezx.apply_sync_v2_attendance_command(text,text,text,text,text,bigint,jsonb,bigint)','rakeezx.apply_sync_v2_attendance_command_before_student_0029(text,text,text,text,text,bigint,jsonb,bigint)','rakeezx.apply_sync_v2_class_goal_reward_command(text,text,text,text,bigint)','rakeezx.apply_sync_v2_class_goal_reward_command_before_student_0029(text,text,text,text,bigint)','rakeezx.apply_sync_v2_closed_term_report_command(text,text,text,text,text,text,jsonb,jsonb,bigint)','rakeezx.apply_sync_v2_closed_term_report_command_before_student_0029(text,text,text,text,text,text,jsonb,jsonb,bigint)','rakeezx.apply_sync_v2_enrollment_command(text,text,text,jsonb,bigint)','rakeezx.apply_sync_v2_enrollment_command_before_student_0029(text,text,text,jsonb,bigint)','rakeezx.apply_sync_v2_fill_attendance_command(text,text,text,text,bigint)','rakeezx.apply_sync_v2_fill_attendance_command_before_student_0029(text,text,text,text,bigint)','rakeezx.apply_sync_v2_lifecycle_command(text,text,text,text,bigint)','rakeezx.apply_sync_v2_lifecycle_command_before_n77(text,text,text,text,bigint)','rakeezx.apply_sync_v2_lifecycle_command_before_section_archive_0021(text,text,text,text,bigint)','rakeezx.apply_sync_v2_lifecycle_command_before_student_0029(text,text,text,text,bigint)','rakeezx.apply_sync_v2_mutation(text,text,text,text,bigint,jsonb,text,bigint)','rakeezx.apply_sync_v2_mutation_before_student_0029(text,text,text,text,bigint,jsonb,text,bigint)','rakeezx.apply_sync_v2_section_lifecycle_command(text,text,text,text,date,bigint)','rakeezx.apply_sync_v2_section_lifecycle_command_before_student_0029(text,text,text,text,date,bigint)','rakeezx.apply_sync_v2_selected_attendance_command(text,text,text,text[],text,bigint)','rakeezx.apply_sync_v2_session_delete_command(text,text,text,bigint)','rakeezx.apply_sync_v2_session_delete_command_before_student_0029(text,text,text,bigint)','rakeezx.apply_sync_v2_teaching_creation_command(text,text,text,text,text,text,integer,jsonb,bigint)','rakeezx.apply_sync_v2_teaching_creation_command_before_student_0029(text,text,text,text,text,text,integer,jsonb,bigint)','rakeezx.apply_unified_student_grade_import(text,text,jsonb)','rakeezx.finalize_n71_restore(text,text,text)','rakeezx.finalize_sync_v2_restore(text,text,text)','rakeezx.finalize_sync_v2_restore_before_n58(text,text,text)','rakeezx.finalize_sync_v2_restore_before_score_0033(text,text,text)','rakeezx.finalize_sync_v2_restore_before_student_0029(text,text,text)','rakeezx.finalize_sync_v2_restore_score_v2(text,text,text)','rakeezx.finalize_sync_v2_restore_score_v2_before_n58(text,text,text)','rakeezx.n36_delete_subjectless_section(text,text,text,text,text,text,boolean)','rakeezx.n77_delete_teaching(text,text,text,text,text,boolean)','rakeezx.commit_enrollment_transfer(jsonb,jsonb)','rakeezx.commit_enrollment_transfer_and_renumber(jsonb,jsonb,jsonb,jsonb)','rakeezx.provision_account_workspace(jsonb)','rakeezx.rename_score_item(text,text,text,bigint,text)','rakeezx.renumber_enrollment_roster(text,jsonb)']::regprocedure[]) OR (p.pronamespace='n88_private'::regnamespace AND (p.proname ~ '^v2_[a-f0-9]{24}$' OR p.proname IN ('v2_runtime_identity_1031','v2_writer_lock_1031','v2_writer_after_1031','v2_writer_retire_1031'))) ORDER BY signature LIMIT 65;
SELECT c.relname,t.tgname,pg_get_triggerdef(t.oid,true) AS definition,t.tgfoid::regprocedure::text AS function FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relnamespace='rakeezx'::regnamespace AND t.tgname IN ('00_n88_global_1031','zz_n88_retire_1031') ORDER BY c.relname,t.tgname LIMIT 24;
SELECT rolname,rolcanlogin,rolsuper,rolbypassrls,rolcreaterole,rolcreatedb,rolinherit,rolconfig FROM pg_roles WHERE rolname IN ('n88_backend','n88_v2_guard','n88_v2_runtime') ORDER BY rolname;
SELECT pg_get_userbyid(roleid) AS role_name,pg_get_userbyid(member) AS member_name,pg_get_userbyid(grantor) AS grantor,admin_option,inherit_option,set_option FROM pg_auth_members WHERE roleid='n88_v2_guard'::regrole AND member IN ('postgres'::regrole,'n88_backend'::regrole) ORDER BY grantor;
SELECT c.relname,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner) AS owner,has_any_column_privilege('n88_backend',c.oid,'SELECT,INSERT,UPDATE,REFERENCES') AS backend_columns,has_table_privilege('n88_backend',c.oid,'DELETE,TRUNCATE,TRIGGER') AS backend_table FROM pg_class c WHERE c.relnamespace='n88_private'::regnamespace AND c.relname IN ('publication_v2_scopes','publication_v2_items','publication_v2_high_water','publication_v2_receipts') ORDER BY c.relname;
